// Every key in this file is generated by the test itself and never printed: a failure
// message names the field that is wrong, not its value.

var privateKeyHexRe = regexp.MustCompile(`^0x[0-9a-f]{64}$`)

// runKeysGenerate runs `rail0 keys generate --json` through its RunE, capturing both
// streams. The global --json is set the way the root sets it — flag, then
// applyOutputMode — and fully reset afterwards (value and Changed), so no other test
// inherits JSON mode.
func runKeysGenerate(t *testing.T) (stdout, stderr string) {
	t.Helper()
	if err := rootCmd.PersistentFlags().Set("json", "true"); err != nil {
		t.Fatal(err)
	}
	applyOutputMode()
	t.Cleanup(func() {
		jsonOut = false
		rootCmd.PersistentFlags().Lookup("json").Changed = false
		ui.SetJSON(false)
	})
	var runErr error
	stderr = captureStderr(t, func() {
		stdout = captureStdout(t, func() { runErr = keysGenerateCmd.RunE(keysGenerateCmd, nil) })
	})
	if runErr != nil {
		t.Fatalf("keys generate: %v", runErr)
	}
	return stdout, stderr
}

func decodeGenerated(t *testing.T, stdout string) generatedWallet {
	t.Helper()
	dec := json.NewDecoder(strings.NewReader(stdout))
	dec.DisallowUnknownFields()
	var w generatedWallet
	if err := dec.Decode(&w); err != nil {
		t.Fatalf("stdout is not the {address, private_key} JSON object: %v", err)
	}
	if dec.More() {
		t.Fatal("stdout carries more than one JSON value")
	}
	return w
}

func TestKeysGenerateIsUnderKeys(t *testing.T) {
	sub, _, err := keysCmd.Find([]string{"generate"})
	if err != nil || sub != keysGenerateCmd {
		t.Fatalf("keys generate: not found (%v)", err)
	}
	// No flags of its own: --json/--pretty/--quiet are the global output flags, and a
	// --no-warning must never exist.
	keysGenerateCmd.LocalNonPersistentFlags().VisitAll(func(f *pflag.Flag) {
		if f.Name != "help" {
			t.Errorf("keys generate should define no flags of its own, has --%s", f.Name)
		}
	})
}

// The key must be a valid secp256k1 key whose address is the one printed: re-derive
// it through the CLI's own parser (the one every signing command uses).
func TestGenerateWalletKeyMatchesAddress(t *testing.T) {
	w, err := generateWallet()
	if err != nil {
		t.Fatal(err)
	}
	if !privateKeyHexRe.MatchString(w.PrivateKey) {
		t.Error("private_key is not 0x + 64 lowercase hex digits")
	}
	derived, err := addressFromKey(w.PrivateKey)
	if err != nil {
		t.Fatalf("generated key does not parse: %v", err)
	}
	if derived != w.Address {
		t.Error("address does not match the address derived from private_key")
	}
	if !common.IsHexAddress(w.Address) || common.HexToAddress(w.Address).Hex() != w.Address {
		t.Error("address is not EIP-55 checksummed")
	}
}

func TestGenerateWalletIsFreshEachTime(t *testing.T) {
	a, err := generateWallet()
	if err != nil {
		t.Fatal(err)
	}
	b, err := generateWallet()
	if err != nil {
		t.Fatal(err)
	}
	if a.PrivateKey == b.PrivateKey || a.Address == b.Address {
		t.Error("two runs produced the same key pair")
	}
}

// --json: stdout is exactly one clean JSON object {address, private_key}, valid and
// consistent; the warning is entirely on stderr and never carries the key.
func TestKeysGenerateJSONOnStdoutWarningOnStderr(t *testing.T) {
	stdout, stderr := runKeysGenerate(t)

	w := decodeGenerated(t, stdout)
	if !privateKeyHexRe.MatchString(w.PrivateKey) {
		t.Error("private_key is not 0x + 64 lowercase hex digits")
	}
	if derived, err := addressFromKey(w.PrivateKey); err != nil || derived != w.Address {
		t.Error("printed address does not match the printed private key")
	}
	if strings.Contains(stderr, "\x1b[") {
		t.Error("warning to a non-terminal stderr carries ANSI escapes")
	}
	if strings.Contains(stdout, "WARNING") {
		t.Error("the warning leaked into stdout — it would corrupt --json")
	}

	for _, want := range []string{
		"shown only once",
		"cannot be recovered",
		"password manager",
		"controls the funds",
		"shell history",
		"scrollback",
		"screen sharing",
		"Never paste it into a website",
		"never share it with RAIL0 operators",
		"stdout is not a terminal", // captured through a pipe
	} {
		if !strings.Contains(stderr, want) {
			t.Errorf("warning on stderr is missing %q", want)
		}
	}
	if strings.Contains(stderr, w.PrivateKey) || strings.Contains(stderr, strings.TrimPrefix(w.PrivateKey, "0x")) {
		t.Error("the private key appeared on stderr")
	}
}

func TestKeysGenerateRunsAreIndependent(t *testing.T) {
	out1, _ := runKeysGenerate(t)
	out2, _ := runKeysGenerate(t)
	if decodeGenerated(t, out1).PrivateKey == decodeGenerated(t, out2).PrivateKey {
		t.Error("two runs printed the same private key")
	}
}

// The terminal warning names no redirection when stdout is a terminal.
func TestGeneratedKeyWarningOnATerminal(t *testing.T) {
	var b strings.Builder
	printGeneratedKeyWarning(&b, false, false)
	if strings.Contains(b.String(), "stdout is not a terminal") {
		t.Error("the redirection reminder must only appear when stdout is redirected")
	}
	if !strings.Contains(b.String(), "WARNING") {
		t.Error("warning missing")
	}
	if strings.Contains(b.String(), "\x1b[") {
		t.Error("unstyled warning carries ANSI escapes")
	}
}

// trapTransport fails — and counts — any HTTP request that reaches it.
type trapTransport struct{ hits atomic.Int32 }

func (tt *trapTransport) RoundTrip(*http.Request) (*http.Response, error) {
	tt.hits.Add(1)
	return nil, errors.New("network access is forbidden in keys generate")
}

// Offline, at runtime: with every HTTP client in the process routed to a trap (the
// SDK and the update check both fall back to http.DefaultTransport) and HOME/XDG
// pointed at an empty directory, a run makes no request and writes no file — no
// config, no session, no keychain index.
func TestKeysGenerateMakesNoRequestAndWritesNothing(t *testing.T) {
	trap := &trapTransport{}
	saved := http.DefaultTransport
	http.DefaultTransport = trap
	t.Cleanup(func() { http.DefaultTransport = saved })

	dir := t.TempDir()
	t.Setenv("HOME", dir)
	t.Setenv("XDG_CONFIG_HOME", filepath.Join(dir, "config"))
	t.Setenv("XDG_CACHE_HOME", filepath.Join(dir, "cache"))
	t.Setenv("RAIL0_BASE_URL", "https://gateway.invalid")

	runKeysGenerate(t)

	if n := trap.hits.Load(); n != 0 {
		t.Errorf("keys generate made %d HTTP request(s)", n)
	}
	entries, err := os.ReadDir(dir)
	if err != nil {
		t.Fatal(err)
	}
	if len(entries) != 0 {
		t.Errorf("keys generate wrote to disk: %v", entries)
	}
}

// Offline, structurally: the command's source imports nothing that can reach the
// network, the keychain or the config, and calls none of the CLI's client or config
// constructors. A future edit that wires any of them in fails here, before review.
func TestKeysGenerateSourceIsOffline(t *testing.T) {
	f, err := parser.ParseFile(token.NewFileSet(), "keys_generate.go", nil, 0)
	if err != nil {
		t.Fatal(err)
	}
	forbiddenImports := []string{
		"net", "github.com/commercelayer/rail0-go", "github.com/zalando/go-keyring",
		"github.com/rail0/cli/internal/config", "github.com/rail0/cli/internal/token",
		"github.com/rail0/cli/internal/selfupdate",
	}
	for _, imp := range f.Imports {
		path, _ := strconv.Unquote(imp.Path.Value)
		for _, bad := range forbiddenImports {
			if path == bad || strings.HasPrefix(path, bad+"/") {
				t.Errorf("keys_generate.go imports %s", path)
			}
		}
	}
	forbiddenCalls := map[string]bool{
		"newClient": true, "newClientFor": true, "newReadClient": true,
		"loadConfig": true, "loadConfigForWrite": true, "resolveBaseURL": true,
		"maybeOfferUpdate": true, "WriteFile": true, "Create": true, "OpenFile": true,
	}
	ast.Inspect(f, func(n ast.Node) bool {
		call, ok := n.(*ast.CallExpr)
		if !ok {
			return true
		}
		var name string
		switch fn := call.Fun.(type) {
		case *ast.Ident:
			name = fn.Name
		case *ast.SelectorExpr:
			name = fn.Sel.Name
		}
		if forbiddenCalls[name] {
			t.Errorf("keys_generate.go calls %s", name)
		}
		return true
	})
}

// The automatic update check (a GitHub request, possibly a binary swap) must skip
// this command, while the rest of `keys` keeps its existing behaviour.
func TestKeysGenerateSkipsTheUpdateCheck(t *testing.T) {
	if !updateCheckSkippedFor(keysGenerateCmd) {
		t.Error("the update check must skip 'keys generate'")
	}
	if updateCheckSkippedFor(keysAddCmd) {
		t.Error("only 'keys generate' is exempt, not the whole keys tree")
	}
	if !updateCheckSkippedFor(updateCmd) {
		t.Error("top-level exemptions must still apply")
	}
	if !localOnlyCommands["keys"] {
		t.Error("keys (and so keys generate) must be exempt from the base-URL check")
	}
}
